    /**
     * Starts the download sequence for the current device
     *
     * @memberof ViewManager
     */
    downloadJSON(): void  {
        if(this.currentDevice === null){
            throw new Error("No device loaded");
        }
        const errorList: Array<SerializationError> = [];
        const fullJson = this.generateExportJSON(errorList);
        const name = this.currentDevice.name || "device";
        const fullText = JSON.stringify(fullJson);
        const portsJson = stripToFlowControlPorts(fullJson);
        const zip = new JSZip();
        zip.file(`${name}.json`, fullText);
        zip.file(`${name}_ports.json`, JSON.stringify(portsJson));
        zip.generateAsync({ type: "blob" }).then(blob => {
            saveAs(blob, `${name}_json.zip`);
        }).catch(err => {
            console.error("[Export JSON]", err);
            const message = err && err.message ? err.message : String(err);
            alert(`Unable to export JSON: ${message}`);
        });

        if (errorList.length > 0) {
            // Concatenate all the errors into a single string with newlines and save it as a file
            let errorString = "";
            for (const error of errorList) {
                errorString += error.toText() + "\n\n";
            }
            const errorBlob = new Blob([errorString], {
                type: "text/plain"
            });
            saveAs(errorBlob, this.currentDevice.name + "_errors.txt");
        }
    }

    createNewDevice(name: string): void {
        let device = new Device({"x-span": 135000, "y-span": 85000}, name);
        console.log("Created new device: ", device.getXSpan(), device.getYSpan());
        this.clear();
        this.__currentDevice = device;
        this.resetPortsOnlyView();
        // TODO -  Clean up lifecyle for active rendered layers
        this.activeRenderLayerIndex = 0;
        this.createNewLayerBlock();
        // TODO - Generate render layers
        generateRenderLayers(this.__currentDevice);
        this.setNameMap();

        Registry.currentDevice = device;

        this.activeRenderLayerIndex = 0;

        this.addDevice(device);

        // In case of MINT exported json, generate layouts for rats nests
        this.__initializeRatsNest();

        this.view.initializeView();
        this.updateGrid();
        this.updateDevice(Registry.currentDevice!);
        this.refresh(true);
        this.currentLayer = this.renderLayers[0];
        this.updateActiveLayer();

    }

    /**
     * Ridiculously convoluted method to return the render layers corresponding to the current level
     * To be used in the case of creating multi-level components
     * @returns {[any, any, any]}
     * @memberof ViewManager
     */
    getCurrentLevelRenderLayers(): [RenderLayer | null , RenderLayer | null , RenderLayer | null] {
        // Get the current level
        const currentLevel = this.activeRenderLayerIndex % 3;
        let currentFlowLayerIndex = currentLevel * 3 + 0;
        let currentControlLayerIndex = currentLevel * 3 + 1;
        let currentIntegrationLayerIndex = currentLevel * 3 + 2;
        return [this.renderLayers[currentFlowLayerIndex], this.renderLayers[currentControlLayerIndex], this.renderLayers[currentIntegrationLayerIndex]];
    }


